def _segments(text, spans):
    out = []
    for s in spans:
        if isinstance(s, str):
            out.append(s)
        elif isinstance(s, dict):
            if "text" in s:
                out.append(str(s.get("text", "")))
            else:
                a = int(s.get("start", s.get("begin", 0)))
                b = int(s.get("end", s.get("stop", a)))
                out.append(text[a:b])
        elif isinstance(s, (list, tuple)) and len(s) >= 2:
            out.append(text[int(s[0]):int(s[1])])
        else:
            out.append("")
    return out

def _has(s, words):
    return any(w in s for w in words)

def _head(s):
    t = s.strip()
    q = t.lower()
    if not t:
        return False
    if len(t) < 18 and not t.replace(".", "").replace("(", "").replace(")", "").replace(" ", "").isdigit() and t.endswith(":"):
        return True
    if len(t) < 100 and t.upper() == t and any(c.isalpha() for c in t):
        return True
    return len(q) < 90 and _has(q, ("definitions and interpretation", "obligations of confidentiality", "permitted disclosures", "return of information", "return of confidential", "excluded information", "term and termination", "other matters", "general provisions"))

def _lead(out, xs, i):
    j = i - 1
    while j >= 0:
        q = xs[j].strip().lower()
        if _head(xs[j]):
            break
        if q.endswith(":") or q.endswith("as follows") or q in ("the recipient shall", "the receiving party shall", "recipient agrees", "the parties shall"):
            out.add(j)
            j -= 1
        else:
            break

def _intro(out, xs, i):
    j = i - 1
    while j >= 0 and not _head(xs[j]):
        q = xs[j].lower()
        if _has(q, ("shall not include", "does not include", "shall not apply", "do not apply", "exceptions", "exclusions", "not be deemed confidential")):
            out.add(j)
            return
        if len(q) > 350:
            return
        j -= 1

def _govern(out, xs, i):
    j = i - 1
    while j >= 0 and not _head(xs[j]):
        q = xs[j].lower()
        if _has(q, ("recipient shall", "receiving party shall", "recipient agrees", "recipient undertakes", "the parties shall")) and (q.endswith(":") or _has(q, ("confidential information", "information"))):
            out.add(j)
            return
        j -= 1

def _defs(xs):
    blocks = []
    for i, s in enumerate(xs):
        q = s.lower()
        if _has(q, ('"confidential information" means', "confidential information shall mean", '"information" shall', '"proprietary information" shall', '"evaluation material" means')):
            e = i + 1
            while e < len(xs):
                z = xs[e].strip().lower()
                if _head(xs[e]) or (z.startswith('"') and " means" in z and "confidential information" not in z):
                    break
                e += 1
            blocks.append((i, e))
    return blocks

def _representative_definition(out, xs, word):
    for i, s in enumerate(xs):
        q = s.lower()
        if word in q and " means" in q and _has(q, ("employee", "agent", "advisor", "adviser", "consultant", "contractor", "lawyer", "accountant")):
            out.add(i)

